"""Victim protection and summons with historical cross-reference guards."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CPC='https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm'
LAW='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm'
S455='https://processo.stj.jus.br/SCON/sumstj/toc.jsp?sumula=455.num.'
PRES='https://noticias.stf.jus.br/postsnoticias/prescricao-em-processo-suspenso-deve-ser-limitada-a-pena-maxima-prevista-para-o-crime/'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add('350-a','Lei 15.280/2025 permite proteção urgente por indícios de crime contra dignidade sexual e estende regime a vítimas vulneráveis, qualquer que seja crime investigado.', ['Medidas isoladas ou conjuntas: armas, afastamento, distância/contato/lugares, visitas com equipe, alimentos, programas e acompanhamento psicossocial.', 'Outras medidas cabíveis, comunicadas ao MP; CPC no que couber.', 'Restrição de arma de agente autorizado: comunicar instituição e responsabilidade de superior pela execução conforme caso.', 'Auxílio policial pode ser requisitado.', '§5º: cumular monitoração e disponibilizar dispositivo de alerta à vítima.', '§6º: crianças, adolescentes, pessoas com deficiência ou incapazes na situação de vulnerabilidade, qualquer crime.'], 'Não limitar toda proteção a violência doméstica ou afirmar que medida é pena definitiva. O âmbito do §6º é mais amplo que crime sexual.', 'Indícios de crime sexual permitem afastamento e proibição de contato com proteção efetiva.', 'Vítima criança em situação vulnerável pode estar abrangida mesmo por crime diverso, conforme §6º.', ['Só se aplica a crime sexual em toda hipótese? Não.', 'Há monitoração cumulada e alerta à vítima previstos? Sim.'], 'Proteção urgente','Providência preventiva para segurança e integridade da vítima.',[LAW])
add('350-b','Juiz pode vedar atividade com contato direto com vulnerável a pedido dos legitimados, com prova do crime, autoria indicativa e perigo da liberdade.', ['Pedido da polícia, MP ou vítima.', 'Qualquer fase da investigação ou processo.', 'Decisão requer os três pressupostos enumerados.'], 'Não confundir indício de autoria com condenação nem proibir qualquer trabalho sem nexo com contato vulnerável.', 'Risco concreto em atividade de contato direto com crianças fundamenta pedido de proibição.', 'Profissão sem esse contato não entra automaticamente no objeto específico do artigo.', ['Vítima pode pedir? Sim.', 'A medida dispensa perigo concreto? Não.'], 'Restrição de atividade protetiva','Limite judicial ao contato profissional vulnerável.',[LAW])
add(351,'Citação inicial por mandado é regra quando acusado está no território do juiz que ordenou o ato.', ['Distinguir citação de intimação posterior.', 'Fora do território, regra própria de cooperação.'], 'Não supor que edital é primeira opção por conveniência.', 'Acusado localizado na comarca recebe mandado pessoal.', 'Endereço em outra comarca exige meio pertinente, não edital só por distância.', ['Na área do juiz regra é mandado? Sim.', 'Distância por si torna edital primeira opção? Não.'], 'Citação inicial','Chamamento regular do acusado para defesa.')
add(352,'Mandado identifica juiz, acusado e finalidade e contém dados e assinaturas previstos.', ['Querelante nas ações por queixa.', 'Nome ou sinais do acusado; residência conhecida.', 'Juízo, local, dia e hora pertinentes.', 'Subscrição do escrivão e rubrica do juiz.'], 'Integrar procedimento atual de resposta à acusação: não transformar menção histórica a comparecimento em supressão do prazo de defesa.', 'Mandado individualiza acusado e finalidade do chamamento.', 'Nome desconhecido permite sinais, mas não citar pessoa física errada.', ['Sinais característicos podem identificar acusado? Sim.', 'Deve indicar finalidade? Sim.'], 'Conteúdo do mandado','Informações que viabilizam ciência e defesa.')
add(353,'Acusado fora da jurisdição territorial é citado por precatória nas hipóteses nacionais.', ['Juízo deprecante pede diligência ao deprecado.', 'Exterior em lugar sabido segue rogatória.'], 'Não confundir precatória nacional com cooperação internacional.', 'Acusado em outra comarca recebe diligência deprecada.', 'Acusado em país estrangeiro com localização sabida exige art. 368.', ['Precatória se refere à cooperação territorial aqui? Sim.', 'Exterior em lugar sabido é hipótese idêntica? Não.'], 'Citação deprecada','Chamamento por cooperação entre juízos.')
add(354,'Precatória identifica juízos e sedes, finalidade com especificações e dados de comparecimento.', ['Identificar deprecante e deprecado.', 'Finalidade precisa e dados do ato.', 'Integrar forma atual de resposta à acusação.'], 'Comunicação entre juízos não dispensa clareza para o destinatário exercer defesa.', 'Carta indica órgão solicitante, destinatário e finalidade.', 'Pedido genérico sem identificação do ato não satisfaz as especificações legais.', ['Deve identificar ambos os juízos? Sim.', 'Finalidade genérica basta sempre? Não.'], 'Requisitos da precatória','Dados necessários à cooperação de citação.')
add(355,'Precatória retorna após cumprimento; localização em outra jurisdição permite remessa útil, e ocultação certificada leva ao regime de hora certa.', ['Cumpra-se e mandado do deprecado.', 'Remessa a outro juiz se há tempo para citação.', 'Ocultação certificada: devolução para art. 362.'], 'Não equiparar não encontrado a ocultação deliberada sem certificação.', 'Réu localizado em outra comarca permite remessa ao juízo adequado com tempo útil.', 'Ocultação comprovada exige observar hora certa, não edital automático.', ['Pode haver remessa ao juízo onde encontrado se há tempo? Sim.', 'Ocultação é igual a mero endereço desconhecido? Não.'], 'Cumprimento itinerante','Encaminhamento e devolução segundo resultado da diligência.')
add(356,'Texto prevê expedição telegráfica urgente com autenticação; estudar a finalidade histórica e integrar comunicação oficial atual.', ['Requisitos resumidos do art. 354.', 'Autenticidade do emissor é essencial.', 'Não afirmar que telegrama é único meio contemporâneo possível.'], 'Mensagem informal não equivale automaticamente a comunicação judicial autenticada; regime digital depende de regras aplicáveis.', 'Diligência urgente é comunicada por canal judicial formal com dados e autenticidade.', 'Mensagem sem identificação confiável não autoriza presumir citação válida.', ['Urgência elimina autenticidade? Não.', 'Texto histórico impõe exclusivamente telegrama para todo ato atual? Não.'], 'Comunicação urgente','Celeridade com identificação e controle.')
add(357,'Oficial lê mandado, entrega contrafé com data e hora e certifica entrega e aceitação ou recusa.', ['Ciência e registro da diligência.', 'Recusa é registrada, não substituída por assinatura fictícia.'], 'Recusa de receber não se confunde com ausência de tentativa regular; examinar ato documentado.', 'Oficial lê, entrega e certifica citação com dia e hora.', 'Recusa é fielmente registrada em certidão.', ['Contrafé deve mencionar dia e hora? Sim.', 'Recusa deve ser ocultada na certidão? Não.'], 'Contrafé','Via fornecida ao citando com registro do ato.')
add(358,'Citação militar ocorre por intermédio do chefe do serviço, com garantia de ciência regular do acusado.', ['Canal funcional específico.', 'Não dispensa chamamento individual para defesa.'], 'Comunicar chefe não significa permitir condenar militar sem citação regular ou defesa.', 'Diligência chega por chefe do serviço conforme regra.', 'Rotina militar não elimina direitos de resposta e assistência técnica.', ['Há intermédio do chefe do serviço? Sim.', 'Isso elimina direito de defesa? Não.'], 'Citação do militar','Comunicação pelo canal funcional previsto.')
add(359,'Data para servidor acusado comparecer é notificada a ele e ao chefe da repartição.', ['Dupla comunicação funcional.', 'Finalidade de viabilizar comparecimento sem confundir chefe com réu.'], 'Avisar chefe não substitui notificar próprio acusado.', 'Servidor e chefia recebem informação da data.', 'Não considerar cientificado acusado só porque chefe leu aviso informal.', ['Deve notificar servidor e chefe? Sim.', 'Chefe passa a ser acusado por receber aviso? Não.'], 'Notificação funcional','Ciência pessoal e institucional do ato.')
add(360,'Acusado preso deve ser citado pessoalmente.', ['Prisão não dispensa ciência direta.', 'Conferir localização e pessoa efetivamente citada.'], 'Não usar edital apenas porque acusado está preso; integrar Súmula 351/STF quando cabível.', 'Oficial cita pessoalmente no estabelecimento onde réu está custodiado.', 'Requisitar transporte não equivale automaticamente a citação documentada.', ['Réu preso é citado pessoalmente? Sim.', 'Prisão dispensa citação? Não.'], 'Ciência do preso','Chamamento pessoal mesmo em custódia.')
add(361,'Sem localização após diligências adequadas, edital tem prazo de quinze dias.', ['Edital é citação ficta, não substituto conveniente de busca real.', 'Ocultação conhecida tem hora certa, não necessariamente edital.'], 'Não considerar esgotamento de diligências só por uma tentativa insuficiente no endereço.', 'Após medidas razoáveis sem localizar acusado, juiz determina edital de quinze dias.', 'Se réu está localizado e se esconde, verificar art. 362.', ['Prazo previsto é quinze dias? Sim.', 'Edital é escolha livre sem tentar localizar? Não.'], 'Citação por edital','Chamamento fictício após não localização adequada.')
add(362,'Ocultação para evitar citação certificada permite hora certa, integrada aos arts. 252–254 do CPC atual.', ['Remissão textual ao CPC/1973 é antiga: CPC/2015 substituiu disciplina.', 'Suspeita fundada de ocultação e formalidades de retorno, ciência e comunicação.', 'Completada hora certa, ausência exige defensor dativo.'], 'Não confundir com art. 366: hora certa não é edital sem defesa. Não treinar arts. 227–229 do CPC revogado como referência atual.', 'Oficial documenta ocultação e cumpre formalidades atuais da hora certa.', 'Ausente após ato completo, assegurar defesa dativa, sem suspensão automática do edital.', ['A remissão numérica ao CPC antigo deve ser atualizada? Sim.', 'Hora certa sem presença elimina defensor? Não.'], 'Hora certa','Citação por ocultação com formalidades e defesa.',[CPC])
add(363,'Formação processual se completa com citação; edital e comparecimento posterior seguem as regras legais.', ['Não localizado: edital.', 'Ao comparecer citado por edital, aplicar arts. 394 e seguintes.', 'Incisos revogados e parágrafos vetados não são comandos atuais.'], 'Não tratar citação como condenação nem restaurar conteúdo vetado.', 'Acusado é citado e passa a exercer defesa no procedimento.', 'Comparecimento após edital ativa procedimento pertinente, respeitando atos válidos e garantias.', ['Citação completa formação na regra? Sim.', 'Parágrafo vetado pode ser exigido como obrigação? Não.'], 'Formação da relação processual','Chamamento que integra acusado ao processo.')
add(364,'Artigo conserva prazos ligados a incisos do art. 363 que foram revogados; não constitui regra atual geral de edital.', ['Remissão antiga a inciso I: quinze a noventa; II: trinta.', 'Art. 361 atual fixa quinze dias para hipótese própria.', 'Distinguir corpo histórico de regra operacional vigente.'], 'Não ensinar trinta ou até noventa como alternativas universais atuais por este artigo.', 'Aluno encontra redação residual e usa art. 361 na hipótese atual de não localização.', 'Questão que invoca antigo inciso precisa ser tratada como histórica, não treino automático vigente.', ['Incisos antigos do 363 continuam ativos? Não.', 'Este residual substitui prazo atual do 361? Não.'], 'Remissão residual','Texto dependente de dispositivos revogados.')
add(365,'Edital identifica órgão, acusado, finalidade, ato e prazo, com publicação/afixação e comprovação.', ['Prazo começa da publicação na imprensa, se houver, ou afixação na hipótese.', 'Dados conhecidos de residência/profissão e sinais se nome desconhecido.', 'Formalidades e prova da publicação; integrar meios oficiais atuais aplicáveis.'], 'Não contar prazo de elaboração interna sem marco de publicidade pertinente.', 'Edital é publicado e certificado com data para contagem.', 'Publicação não certificada exige verificar regularidade, sem pressupor ciência real.', ['Prazo começa só pela assinatura interna? Não.', 'Publicação/afixação devem ser comprovadas? Sim.'], 'Publicidade do edital','Divulgação formal que inicia prazo pertinente.')
add(366,'Citado por edital que não comparece nem constitui advogado tem processo e prescrição suspensos, com controles específicos.', ['Condições cumulativas de ausência e falta de advogado.', 'Urgência probatória concretamente fundamentada; Súmula 455/STJ afasta mero tempo como razão única.', 'Suspensão prescricional limitada pelo prazo correspondente ao máximo cominado, conforme Súmula 415 e Tema 438/STF; processo pode continuar suspenso.', 'Preventiva depende requisitos, provocação e risco: edital não a torna automática.', 'Antecipação preserva defesa técnica; peculiaridades reais de testemunhas podem ser analisadas, sem regra universal por profissão.'], 'Não declarar crime imprescritível pela suspensão nem reiniciar processo automaticamente só porque prescrição voltou a correr.', 'Sem réu e sem advogado após edital, processo é suspenso e urgência de prova realmente perecível é apreciada.', 'Passar tempo isoladamente não fundamenta toda antecipação nem autoriza prender para obrigar comparecimento.', ['A suspensão torna todo crime imprescritível? Não.', 'Tempo isolado basta para prova antecipada? Não.'], 'Suspensão por edital','Pausa com limites e medidas cautelares fundamentadas.',[S455,PRES])
add(367,'Após citação ou intimação pessoal, falta injustificada ou mudança sem aviso pode permitir prosseguimento sem presença física, mantendo defensor.', ['Ausência pessoal não elimina defesa técnica.', 'Justificativa deve ser examinada.', 'Não importar confissão ficta civil para condenação penal.'], 'Revelia penal não presume verdade da acusação nem dispensa prova.', 'Réu pessoalmente intimado falta sem motivo e ato prossegue com defensor.', 'Doença comprovada demanda análise, não revelia automática.', ['Ausência torna acusação verdadeira automaticamente? Não.', 'Defensor continua necessário? Sim.'], 'Prosseguimento sem presença','Continuidade com defesa e prova, sem culpa presumida.')
add(368,'Acusado em lugar conhecido no exterior é citado por rogatória, com prescrição suspensa até cumprimento.', ['Local sabido diferencia do edital.', 'Cooperação internacional nos instrumentos aplicáveis.'], 'Não confundir suspensão até cumprir carta com limite específico do art. 366 por edital.', 'Endereço no exterior conhecido é encaminhado por carta rogatória.', 'Residência estrangeira conhecida não torna acusado não localizado por mera distância.', ['Lugar conhecido no exterior segue rogatória? Sim.', 'A regra é a mesma suspensão por edital? Não.'], 'Citação internacional','Cooperação para chamamento no exterior.')
add(369,'Citação em legações estrangeiras ocorre por carta rogatória nas condições legais.', ['Proteção e cooperação diplomática pertinentes.', 'Não tratar espaço diplomático como destino de mandado doméstico irrestrito.'], 'Regra não elimina imunidades eventualmente aplicáveis nem competência internacional.', 'Diligência em legação segue cooperação legal adequada.', 'Não concluir que rogatória permite qualquer ingresso forçado.', ['O meio indicado é rogatória? Sim.', 'Ela afasta automaticamente imunidade? Não.'], 'Cooperação diplomática','Via formal para diligência em legação.')
add(370,'Intimações seguem regras de citação no que compatível, com distinção entre advogado constituído e nomeado.', ['Constituído, querelante e assistente: publicação incluindo nome do acusado.', 'Sem órgão de publicação: meios previstos/idôneos; ciência pessoal do escrivão dispensa publicação.', 'MP e defensor nomeado: intimação pessoal.', 'Integrar processo eletrônico e prerrogativas legais atuais sem abolir garantias.'], 'Não trocar intimar dativo pessoalmente por publicação comum de advogado constituído.', 'Defensor nomeado recebe intimação pessoal e constituído pelo regime pertinente.', 'Publicação sem nome do acusado exige examinar a nulidade prevista, sem fingir requisito cumprido.', ['Defensor nomeado recebe pessoalmente? Sim.', 'Toda intimação exige o mesmo meio? Não.'], 'Intimação diferenciada','Ciência conforme sujeito e regime aplicável.')
add(371,'Intimação pode ocorrer por despacho na petição em que requerida, observadas formalidades do art. 357.', ['Forma admitida com ciência e registro pertinentes.', 'Não equivale a despacho interno jamais comunicado.'], 'Escrever decisão nos autos não comprova automaticamente intimação válida por essa via.', 'Despacho na petição viabiliza ciência documentada com requisitos.', 'Sem ciência formal pertinente, não presumir prazo iniciado só pelo despacho.', ['Há remissão ao art. 357? Sim.', 'Despacho não comunicado prova sozinho intimação? Não.'], 'Ciência por despacho','Forma de intimação com requisitos legais.')
add(372,'Adiada instrução, juiz fixa desde logo dia e hora de continuação na presença das partes e testemunhas, lavrando termo.', ['Registro da nova data e horário.', 'Ciência dos presentes; ausentes exigem regime aplicável.', 'Adiamento não elimina defesa ou necessidade de regular comunicação.'], 'Não presumir que pessoa ausente ouviu data fixada em audiência.', 'Ao adiar ato, juiz anuncia e documenta continuação aos presentes.', 'Parte ausente demanda verificar sua intimação, não ciência presumida pelo anúncio.', ['Nova data deve constar de termo? Sim.', 'Ausente é automaticamente cientificado pelo anúncio? Não.'], 'Continuação da instrução','Agendamento e registro do ato adiado.')
assert len(rows)==24
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'protection and citations reviewed')
